1	"use client";
2	
3	/**
4	 * Create/edit form bound to `createIssueSchema` through `zodResolver`.
5	 *
6	 * The schema is the same object the Server Action re-parses, so a field the
7	 * client accepts can never be one the server rejects — that shared definition
8	 * is the whole point of keeping the Zod schemas outside both layers.
9	 *
10	 * Must call (do not reimplement): createIssueSchema
11	 */
12	import { zodResolver } from "@hookform/resolvers/zod";
13	import { useForm, useWatch } from "react-hook-form";
14	import { Button } from "@/components/ui/button";
15	import { ErrorMessage } from "@/components/ui/error-message";
16	import { FormField } from "@/components/ui/form-field";
17	import { Input } from "@/components/ui/input";
18	import { Textarea } from "@/components/ui/textarea";
19	import { useFormAction } from "@/hooks/use-form-action";
20	import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
21	import type { ActionResult } from "@/types/api";
22	import type { IsoTimestamp, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
23	import type { Issue, IssueLabel } from "@/types/issue";
24	import type { MemberWithUser } from "@/types/member";
25	import type { ReactElement } from "react";
26	import { IssueAssigneePicker } from "./issue-assignee-picker";
27	import { IssueDueDateField } from "./issue-due-date-field";
28	import { IssueLabelPicker } from "./issue-label-picker";
29	import { IssuePrioritySelect } from "./issue-priority-select";
30	import { IssueStatusSelect } from "./issue-status-select";
31	
32	export type IssueFormProps = {
33	  orgId: OrgId;
34	  projectId: ProjectId;
35	  defaultValues?: Partial<CreateIssueInput>;
36	  members: readonly MemberWithUser[];
37	  labels: readonly IssueLabel[];
38	  onSubmit: (input: CreateIssueInput) => Promise<ActionResult<Issue>>;
39	};
40	
41	export function IssueForm(props: IssueFormProps): ReactElement | null {
42	  const { orgId, projectId, defaultValues, members, labels, onSubmit } = props;
43	
44	  const form = useForm({
45	    resolver: zodResolver(createIssueSchema),
46	    defaultValues: {
47	      orgId,
48	      projectId,
49	      title: "",
50	      description: null,
51	      status: "backlog",
52	      priority: "none",
53	      assigneeId: null,
54	      parentId: null,
55	      estimate: null,
56	      dueAt: null,
57	      labelIds: [],
58	      ...defaultValues,
59	    },
60	  });
61	
62	  const { submit, pending, error } = useFormAction(onSubmit, {
63	    onSuccess: () => form.reset(),
64	  });
65	
66	  const values = useWatch({ control: form.control });
67	  const fieldError = (name: keyof CreateIssueInput): string | null =>
68	    form.formState.errors[name]?.message ?? null;
69	
70	  return (
71	    <form
72	      className="space-y-4"
73	      onSubmit={form.handleSubmit((input) => submit(input))}
74	    >
75	      <FormField
76	        name="title"
77	        label="Title"
78	        required
79	        error={fieldError("title")}
80	      >
81	        <Input
82	          name="title"
83	          value={values.title ?? ""}
84	          placeholder="Something is broken"
85	          invalid={fieldError("title") !== null}
86	          onChange={(value) => form.setValue("title", value)}
87	        />
88	      </FormField>
89	
90	      <FormField name="description" label="Description">
91	        <Textarea
92	          name="description"
93	          rows={6}
94	          value={values.description ?? ""}
95	          placeholder="What happened, and what did you expect?"
96	          onChange={(value) =>
97	            form.setValue("description", value.length === 0 ? null : value)
98	          }
99	        />
100	      </FormField>
101	
102	      <div className="grid gap-4 sm:grid-cols-2">
103	        <FormField name="status" label="Status">
104	          <IssueStatusSelect
105	            value={values.status ?? "backlog"}
106	            onChange={(status) => form.setValue("status", status)}
107	          />
108	        </FormField>
109	
110	        <FormField name="priority" label="Priority">
111	          <IssuePrioritySelect
112	            value={values.priority ?? "none"}
113	            onChange={(priority) => form.setValue("priority", priority)}
114	          />
115	        </FormField>
116	
117	        <FormField name="assigneeId" label="Assignee">
118	          <IssueAssigneePicker
119	            value={(values.assigneeId ?? null) as UserId | null}
120	            members={members}
121	            onChange={(userId) => form.setValue("assigneeId", userId)}
122	          />
123	        </FormField>
124	
125	        <FormField name="dueAt" label="Due date">
126	          <IssueDueDateField
127	            value={(values.dueAt ?? null) as IsoTimestamp | null}
128	            onChange={(dueAt) => form.setValue("dueAt", dueAt)}
129	          />
130	        </FormField>
131	      </div>
132	
133	      <FormField name="labelIds" label="Labels">
134	        <IssueLabelPicker
135	          value={(values.labelIds ?? []) as unknown as readonly LabelId[]}
136	          labels={labels}
137	          onChange={(labelIds) => form.setValue("labelIds", [...labelIds])}
138	        />
139	      </FormField>
140	
141	      <ErrorMessage message={error?.message ?? null} />
142	
143	      <Button type="submit" loading={pending} disabled={pending}>
144	        Create issue
145	      </Button>
146	    </form>
147	  );
148	}
